def datos_existentes(apps, schema_editor):
    """Adapta datos de la versión anterior: direcciones al usuario, slugs de oficios
    y perfiles profesionales que ya tenían oficios cargados."""
    Direccion = apps.get_model('core', 'Direccion')
    Oficio = apps.get_model('core', 'Oficio')
    Profesional = apps.get_model('core', 'Profesional')
    for d in Direccion.objects.filter(usuario__isnull=True, cliente__isnull=False):
        d.usuario_id = d.cliente_id  # Cliente.pk == Usuario.pk
        d.save(update_fields=['usuario'])
    slugs = {'gas': 'gasista', 'elec': 'electricista', 'plom': 'plomero'}
    for o in Oficio.objects.all():
        for k, v in slugs.items():
            if o.nombre.lower().startswith(k) and not o.slug:
                o.slug = v
                o.save(update_fields=['slug'])
    for p in Profesional.objects.all():
        if p.experiencias.exists():
            p.perfil_completo = True
            p.save(update_fields=['perfil_completo'])


